package com.finsightai.controller;
import com.finsightai.dto.*;import com.finsightai.model.AuditLog;import com.finsightai.repository.AuditLogRepository;import com.finsightai.service.AnalyticsService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final AnalyticsService a;private final AuditLogRepository logs;public DashboardController(AnalyticsService a,AuditLogRepository l){this.a=a;logs=l;}@GetMapping("/kpis")public KpiResponse kpis(){return a.kpis();}@GetMapping("/category-spend")public List<CategoryMetric> categories(){return a.categorySpend();}@GetMapping("/trend")public List<Map<String,Object>> trend(){return a.monthlyTrend();}@GetMapping("/audit")public List<AuditLog> audit(){return logs.findTop100ByOrderByTimestampDesc();}}
